+func hosts(host string, ignores []string) ([]string, error) {
+	enumerated, err := enumerateHosts(host)
+	if err != nil {
+		return nil, xerrors.Errorf("Failed to enumerate hosts. err: %w", err)
+	}
+
+	ignored := map[string]struct{}{}
+	for _, ignore := range ignores {
+		hosts, err := enumerateHosts(ignore)
+		if err != nil {
+			return nil, xerrors.Errorf("Failed to enumerate hosts. err: %w", err)
+		}
+		if len(hosts) == 1 && net.ParseIP(hosts[0]) == nil {
+			return nil, xerrors.Errorf("Failed to ignore hosts. err: a non-IP address has been entered in ignoreIPAddresses")
+		}
+		for _, host := range hosts {
+			ignored[host] = struct{}{}
+		}
+	}
+
+	filtered := make([]string, 0, len(enumerated))
+	for _, host := range enumerated {
+		if _, ok := ignored[host]; ok {
+			continue
+		}
+		filtered = append(filtered, host)
+	}
+	return filtered, nil
+}
+
+func enumerateHosts(host string) ([]string, error) {
+	if !isCIDRNotation(host) {
+		return []string{host}, nil
+	}
+
+	ipAddr, ipNet, err := net.ParseCIDR(host)
+	if err != nil {
+		return nil, xerrors.Errorf("Failed to parse CIDR. err: %w", err)
+	}
+
+	maskLen, bits := ipNet.Mask.Size()
+	count := new(big.Int).Lsh(big.NewInt(1), uint(bits-maskLen))
+	if bits == net.IPv6len*8 && count.Cmp(big.NewInt(65536)) == 1 {
+		return nil, xerrors.Errorf("Failed to enumerate IP address. err: mask bitsize too big")
+	}
+	if !count.IsInt64() || count.Int64() > math.MaxInt32 {
+		return nil, xerrors.Errorf("Failed to enumerate IP address. err: mask bitsize too big")
+	}
+
+	start := ipAddr.Mask(ipNet.Mask)
+	if bits == net.IPv4len*8 {
+		start = start.To4()
+	} else {
+		start = start.To16()
+	}
+	if start == nil {
+		return nil, xerrors.Errorf("Failed to enumerate IP address. err: unsupported address")
+	}
+
+	addrs := make([]string, 0, int(count.Int64()))
+	current := append(net.IP(nil), start...)
+	for i := int64(0); i < count.Int64(); i++ {
+		addrs = append(addrs, current.String())
+		incrementIP(current)
+	}
+	return addrs, nil
+}
+
+func incrementIP(ip net.IP) {
+	for i := len(ip) - 1; i >= 0; i-- {
+		ip[i]++
+		if ip[i] != 0 {
+			return
+		}
+	}
+}
+
+func isCIDRNotation(host string) bool {
+	ss := strings.Split(host, "/")
+	if len(ss) != 2 || net.ParseIP(ss[0]) == nil {
+		return false
+	}
+	return true
+}
