diff --git a/server/events/sse_test.go b/server/events/sse_test.go
new file mode 100644
index 00000000..4b9a47b0
--- /dev/null
+++ b/server/events/sse_test.go
@@ -0,0 +1,125 @@
+package events
+
+import (
+	"context"
+
+	"github.com/navidrome/navidrome/model"
+	"github.com/navidrome/navidrome/model/request"
+	. "github.com/onsi/ginkgo"
+	. "github.com/onsi/gomega"
+)
+
+var _ = Describe("broker", func() {
+	newClient := func(ctx context.Context, username, name string) client {
+		return client{
+			id:       name,
+			username: username,
+			name:     name,
+			diode:    newDiode(ctx, 16, nil),
+		}
+	}
+
+	drainServerStart := func(c client) {
+		Eventually(func() string {
+			msg, ok := c.diode.tryNext()
+			if !ok {
+				return ""
+			}
+			return msg.Event
+		}).Should(Equal("serverStart"))
+	}
+
+	It("delivers directed refresh events only to other sessions of the same user", func() {
+		b := &broker{
+			publish:       make(messageChan, 10),
+			subscribing:   make(clientsChan, 10),
+			unsubscribing: make(clientsChan, 10),
+		}
+		go b.listen()
+
+		originCtx, cancelOrigin := context.WithCancel(context.Background())
+		defer cancelOrigin()
+		siblingCtx, cancelSibling := context.WithCancel(context.Background())
+		defer cancelSibling()
+		otherCtx, cancelOther := context.WithCancel(context.Background())
+		defer cancelOther()
+
+		origin := newClient(originCtx, "alice", "client-a")
+		sibling := newClient(siblingCtx, "alice", "client-b")
+		other := newClient(otherCtx, "bob", "client-c")
+
+		b.subscribing <- origin
+		b.subscribing <- sibling
+		b.subscribing <- other
+
+		drainServerStart(origin)
+		drainServerStart(sibling)
+		drainServerStart(other)
+
+		ctx := request.WithUser(context.Background(), model.User{UserName: "alice"})
+		ctx = request.WithClient(ctx, "client-a")
+		b.SendMessage((&RefreshResource{}).WithContext(ctx).With("song", "1"))
+
+		Eventually(func() message {
+			msg, ok := sibling.diode.tryNext()
+			if !ok {
+				return message{}
+			}
+			return *msg
+		}).Should(Satisfy(func(msg message) bool {
+			return msg.Event == "refreshResource" &&
+				msg.Data == `{"song":["1"]}` &&
+				msg.User == "alice" &&
+				msg.Skip == "client-a"
+		}))
+
+		Consistently(func() bool {
+			_, ok := origin.diode.tryNext()
+			return ok
+		}).Should(BeFalse())
+		Consistently(func() bool {
+			_, ok := other.diode.tryNext()
+			return ok
+		}).Should(BeFalse())
+	})
+
+	It("keeps broadcasting non-directed refresh events to every client", func() {
+		b := &broker{
+			publish:       make(messageChan, 10),
+			subscribing:   make(clientsChan, 10),
+			unsubscribing: make(clientsChan, 10),
+		}
+		go b.listen()
+
+		firstCtx, cancelFirst := context.WithCancel(context.Background())
+		defer cancelFirst()
+		secondCtx, cancelSecond := context.WithCancel(context.Background())
+		defer cancelSecond()
+
+		first := newClient(firstCtx, "alice", "client-a")
+		second := newClient(secondCtx, "bob", "client-b")
+
+		b.subscribing <- first
+		b.subscribing <- second
+
+		drainServerStart(first)
+		drainServerStart(second)
+
+		b.SendMessage((&RefreshResource{}).With("album", "10"))
+
+		Eventually(func() string {
+			msg, ok := first.diode.tryNext()
+			if !ok {
+				return ""
+			}
+			return msg.Data
+		}).Should(Equal(`{"album":["10"]}`))
+		Eventually(func() string {
+			msg, ok := second.diode.tryNext()
+			if !ok {
+				return ""
+			}
+			return msg.Data
+		}).Should(Equal(`{"album":["10"]}`))
+	})
+})
