+func normalizeTrivyCveContents(contents models.CveContents) models.CveContents {
+	for ctype, conts := range contents {
+		normalized := make([]models.CveContent, 0, len(conts))
+		seen := map[string]int{}
+		severityIndex := -1
+		severitySet := map[trivydbTypes.Severity]struct{}{}
+
+		for _, cont := range conts {
+			if isSeverityOnlyCveContent(cont) {
+				if severityIndex == -1 {
+					severityIndex = len(normalized)
+					normalized = append(normalized, cont)
+				} else {
+					normalized[severityIndex] = mergeCveContent(normalized[severityIndex], cont)
+				}
+				for _, sev := range splitSeverity(cont.Cvss3Severity) {
+					severitySet[sev] = struct{}{}
+				}
+				continue
+			}
+
+			key := cveContentKey(cont)
+			if idx, ok := seen[key]; ok {
+				normalized[idx] = mergeCveContent(normalized[idx], cont)
+				continue
+			}
+			seen[key] = len(normalized)
+			normalized = append(normalized, cont)
+		}
+
+		if severityIndex != -1 {
+			normalized[severityIndex].Cvss3Severity = joinSeverities(severitySet)
+		}
+		contents[ctype] = normalized
+	}
+	return contents
+}
+
+func isSeverityOnlyCveContent(cont models.CveContent) bool {
+	return cont.Cvss3Severity != "" &&
+		cont.Cvss2Score == 0 &&
+		cont.Cvss2Vector == "" &&
+		cont.Cvss2Severity == "" &&
+		cont.Cvss3Score == 0 &&
+		cont.Cvss3Vector == ""
+}
+
+func cveContentKey(cont models.CveContent) string {
+	return fmt.Sprintf("%s|%s|%s|%f|%s|%s|%f|%s|%s",
+		cont.Type,
+		cont.CveID,
+		cont.SourceLink,
+		cont.Cvss2Score,
+		cont.Cvss2Vector,
+		cont.Cvss2Severity,
+		cont.Cvss3Score,
+		cont.Cvss3Vector,
+		cont.Cvss3Severity,
+	)
+}
+
+func mergeCveContent(dst, src models.CveContent) models.CveContent {
+	if dst.Title == "" {
+		dst.Title = src.Title
+	}
+	if dst.Summary == "" {
+		dst.Summary = src.Summary
+	}
+	if dst.SourceLink == "" {
+		dst.SourceLink = src.SourceLink
+	}
+	if dst.Cvss2Score == 0 {
+		dst.Cvss2Score = src.Cvss2Score
+	}
+	if dst.Cvss2Vector == "" {
+		dst.Cvss2Vector = src.Cvss2Vector
+	}
+	if dst.Cvss2Severity == "" {
+		dst.Cvss2Severity = src.Cvss2Severity
+	}
+	if dst.Cvss3Score == 0 {
+		dst.Cvss3Score = src.Cvss3Score
+	}
+	if dst.Cvss3Vector == "" {
+		dst.Cvss3Vector = src.Cvss3Vector
+	}
+	if dst.Cvss3Severity == "" {
+		dst.Cvss3Severity = src.Cvss3Severity
+	}
+	if dst.Published.IsZero() {
+		dst.Published = src.Published
+	}
+	if dst.LastModified.IsZero() {
+		dst.LastModified = src.LastModified
+	}
+	dst.References = mergeReferences(dst.References, src.References)
+	dst.CweIDs = mergeStrings(dst.CweIDs, src.CweIDs)
+	return dst
+}
+
+func mergeReferences(dst, src models.References) models.References {
+	merged := append(models.References{}, dst...)
+	seen := map[string]struct{}{}
+	for _, ref := range merged {
+		seen[fmt.Sprintf("%s|%s|%s", ref.Source, ref.Link, strings.Join(ref.Tags, ","))] = struct{}{}
+	}
+	for _, ref := range src {
+		key := fmt.Sprintf("%s|%s|%s", ref.Source, ref.Link, strings.Join(ref.Tags, ","))
+		if _, ok := seen[key]; ok {
+			continue
+		}
+		seen[key] = struct{}{}
+		merged = append(merged, ref)
+	}
+	sort.Slice(merged, func(i, j int) bool {
+		return merged[i].Link < merged[j].Link
+	})
+	return merged
+}
+
+func mergeStrings(dst, src []string) []string {
+	merged := append([]string{}, dst...)
+	seen := map[string]struct{}{}
+	for _, s := range merged {
+		seen[s] = struct{}{}
+	}
+	for _, s := range src {
+		if _, ok := seen[s]; ok {
+			continue
+		}
+		seen[s] = struct{}{}
+		merged = append(merged, s)
+	}
+	sort.Strings(merged)
+	return merged
+}
+
+func splitSeverity(raw string) []trivydbTypes.Severity {
+	var severities []trivydbTypes.Severity
+	for _, part := range strings.Split(raw, "|") {
+		part = strings.TrimSpace(part)
+		if part == "" {
+			continue
+		}
+		sev, err := trivydbTypes.NewSeverity(part)
+		if err != nil {
+			continue
+		}
+		severities = append(severities, sev)
+	}
+	return severities
+}
+
+func joinSeverities(severitySet map[trivydbTypes.Severity]struct{}) string {
+	if len(severitySet) == 0 {
+		return ""
+	}
+	severities := make([]trivydbTypes.Severity, 0, len(severitySet))
+	for sev := range severitySet {
+		severities = append(severities, sev)
+	}
+	sort.Slice(severities, func(i, j int) bool {
+		return severities[i] < severities[j]
+	})
+	names := make([]string, 0, len(severities))
+	for _, sev := range severities {
+		names = append(names, trivydbTypes.SeverityNames[sev])
+	}
+	return strings.Join(names, "|")
+}

