diff --git a/src/routes/well-known.js b/src/routes/well-known.js
new file mode 100644
index 0000000000..808d99ccc2
--- /dev/null
+++ b/src/routes/well-known.js
@@ -0,0 +1,103 @@
+'use strict';
+
+const nconf = require('nconf');
+
+const user = require('../user');
+const privileges = require('../privileges');
+const controllerHelpers = require('../controllers/helpers');
+const helpers = require('./helpers');
+
+module.exports = function (app) {
+	app.get('/.well-known/change-password', (req, res) => {
+		res.redirect(`${nconf.get('relative_path')}/me/edit/password`);
+	});
+
+	app.get('/.well-known/webfinger', helpers.tryRoute(handleWebfinger));
+};
+
+async function handleWebfinger(req, res, next) {
+	const userslug = getUserslugFromResource(req.query.resource);
+	if (!userslug) {
+		return res.status(400).json({
+			error: 'invalid-resource',
+		});
+	}
+
+	const canView = await privileges.global.can('view:users', req.uid);
+	if (!canView) {
+		return controllerHelpers.notAllowed(req, res);
+	}
+
+	const uid = await user.getUidByUserslug(userslug.toLowerCase());
+	if (!uid) {
+		return next();
+	}
+
+	const userData = await user.getUserFields(uid, ['userslug']);
+	if (!userData || !userData.userslug) {
+		return next();
+	}
+
+	const siteUrl = nconf.get('url');
+	const siteHost = new URL(siteUrl).host;
+	const profileUrl = `${siteUrl}/user/${userData.userslug}`;
+
+	res
+		.status(200)
+		.type('application/jrd+json')
+		.json({
+			subject: `acct:${userData.userslug}@${siteHost}`,
+			aliases: [profileUrl],
+			links: [
+				{
+					rel: 'http://webfinger.net/rel/profile-page',
+					type: 'text/html',
+					href: profileUrl,
+				},
+			],
+		});
+}
+
+function getUserslugFromResource(resource) {
+	if (typeof resource !== 'string' || !resource.trim()) {
+		return null;
+	}
+
+	const siteUrl = new URL(nconf.get('url'));
+	const siteHost = siteUrl.host.toLowerCase();
+	const trimmed = resource.trim();
+
+	if (trimmed.toLowerCase().startsWith('acct:')) {
+		const match = trimmed.match(/^acct:([^@]+)@(.+)$/i);
+		if (!match || match[2].toLowerCase() !== siteHost) {
+			return null;
+		}
+
+		return safeDecodeURIComponent(match[1]);
+	}
+
+	try {
+		const resourceUrl = new URL(trimmed);
+		if (resourceUrl.origin !== siteUrl.origin) {
+			return null;
+		}
+
+		const basePath = siteUrl.pathname.replace(/\/$/, '');
+		const profilePrefix = `${basePath}/user/`;
+		if (!resourceUrl.pathname.startsWith(profilePrefix)) {
+			return null;
+		}
+
+		return safeDecodeURIComponent(resourceUrl.pathname.slice(profilePrefix.length).split('/')[0]);
+	} catch (err) {
+		return null;
+	}
+}
+
+function safeDecodeURIComponent(value) {
+	try {
+		return decodeURIComponent(value);
+	} catch (err) {
+		return null;
+	}
+}

