diff --git a/src/upgrades/4.4.0/chat_allow_deny_lists.js b/src/upgrades/4.4.0/chat_allow_deny_lists.js
new file mode 100644
index 0000000000..9e8fb38d37
--- /dev/null
+++ b/src/upgrades/4.4.0/chat_allow_deny_lists.js
@@ -0,0 +1,70 @@
+'use strict';
+
+const batch = require('../../batch');
+const db = require('../../database');
+
+module.exports = {
+	name: 'Migrate legacy chat restrictions to explicit allow lists',
+	timestamp: Date.UTC(2026, 4, 7),
+	method: async function () {
+		const { progress } = this;
+
+		await batch.processSortedSet('users:joindate', async (uids) => {
+			progress.incr(uids.length);
+
+			const [settingsList, followingLists] = await Promise.all([
+				db.getObjects(uids.map(uid => `user:${uid}:settings`)),
+				db.getSortedSetsMembers(uids.map(uid => `following:${uid}`)),
+			]);
+
+			const bulkSet = [];
+			settingsList.forEach((settings, index) => {
+				if (parseInt(settings && settings.restrictChat, 10) !== 1) {
+					return;
+				}
+
+				const allowList = parseUidList(settings.chatAllowList).concat(
+					(followingLists[index] || []).map(uid => parseInt(uid, 10)).filter(uid => uid > 0)
+				);
+				const deduped = [...new Set(allowList)];
+				bulkSet.push([
+					`user:${uids[index]}:settings`,
+					{
+						chatAllowList: JSON.stringify(deduped),
+						restrictChat: 0,
+					},
+				]);
+			});
+
+			if (bulkSet.length) {
+				await db.setObjectBulk(bulkSet);
+			}
+		}, {
+			batch: 500,
+			progress: progress,
+		});
+	},
+};
+
+function parseUidList(value) {
+	if (!value) {
+		return [];
+	}
+
+	let values = value;
+	if (typeof values === 'string') {
+		try {
+			values = JSON.parse(values);
+		} catch (err) {
+			values = values.split(',');
+		}
+	}
+
+	if (!Array.isArray(values)) {
+		values = [values];
+	}
+
+	return [...new Set(values
+		.map(uid => parseInt(uid, 10))
+		.filter(uid => uid > 0))];
+}
