+++ b/model/album_artist.go
@@ -0,0 +1,51 @@
+package model
+
+import (
+	sliceutil "github.com/navidrome/navidrome/utils/slice"
+	"golang.org/x/exp/slices"
+)
+
+func (aa Albums) ToAlbumArtist() Artist {
+	a := Artist{AlbumCount: len(aa)}
+	var mbzArtistIDs []string
+	genres := map[string]Genre{}
+
+	for _, album := range aa {
+		if a.ID == "" {
+			a.ID = album.AlbumArtistID
+		}
+		if a.Name == "" {
+			a.Name = album.AlbumArtist
+		}
+		if a.SortArtistName == "" {
+			a.SortArtistName = album.SortAlbumArtistName
+		}
+		if a.OrderArtistName == "" {
+			a.OrderArtistName = album.OrderAlbumArtistName
+		}
+
+		a.SongCount += album.SongCount
+		a.Size += album.Size
+
+		if album.MbzAlbumArtistID != "" {
+			mbzArtistIDs = append(mbzArtistIDs, album.MbzAlbumArtistID)
+		}
+
+		for _, genre := range album.Genres {
+			if genre.ID == "" {
+				continue
+			}
+			if current, ok := genres[genre.ID]; !ok || (current.Name == "" && genre.Name != "") {
+				genres[genre.ID] = genre
+			}
+		}
+	}
+
+	for _, genre := range genres {
+		a.Genres = append(a.Genres, genre)
+	}
+	slices.SortFunc(a.Genres, func(a, b Genre) bool { return a.ID < b.ID })
+	a.MbzArtistID = sliceutil.MostFrequent(mbzArtistIDs)
+
+	return a
+}
