+const apkListPattern = `(?P<pkgver>.+) (?P<arch>.+) \{(?P<origin>.+)\} \(.+\) \[(?P<status>.+)\]`
+
+func (o *alpine) parseApkInstalledList(stdout string) (models.Packages, models.SrcPackages, error) {
+	binaries := models.Packages{}
+	sources := models.SrcPackages{}
+
+	re, err := regexp.Compile(apkListPattern)
+	if err != nil {
+		return nil, nil, xerrors.Errorf("Failed to compile pattern for apk list. err: %w", err)
+	}
+
+	for _, match := range re.FindAllStringSubmatch(stdout, -1) {
+		if match[re.SubexpIndex("status")] != "installed" {
+			return nil, nil, xerrors.Errorf("Failed to parse `apk list --installed`. err: unexpected status section. expected: %q, actual: %q", "installed", match[re.SubexpIndex("status")])
+		}
+
+		ss := strings.Split(match[re.SubexpIndex("pkgver")], "-")
+		if len(ss) < 3 {
+			return nil, nil, xerrors.Errorf("Failed to parse `apk list --installed`. err: unexpected package name and version section. expected: %q, actual: %q", "<name>-<version>-<release>", match[re.SubexpIndex("pkgver")])
+		}
+		name := strings.Join(ss[:len(ss)-2], "-")
+		version := strings.Join(ss[len(ss)-2:], "-")
+		binaries[name] = models.Package{
+			Name:    name,
+			Version: version,
+			Arch:    match[re.SubexpIndex("arch")],
+		}
+
+		srcName := match[re.SubexpIndex("origin")]
+		src, ok := sources[srcName]
+		if !ok {
+			src = models.SrcPackage{
+				Name:    srcName,
+				Version: version,
+			}
+		}
+		src.AddBinaryName(name)
+		sources[srcName] = src
+	}
+
+	return binaries, sources, nil
+}
+
+func (o *alpine) parseApkIndex(stdout string) (models.Packages, models.SrcPackages, error) {
+	binaries := models.Packages{}
+	sources := models.SrcPackages{}
+
+	for _, section := range strings.Split(strings.TrimSuffix(stdout, "\n"), "\n\n") {
+		if strings.TrimSpace(section) == "" {
+			continue
+		}
+
+		var name, srcName, version, arch string
+		scanner := bufio.NewScanner(strings.NewReader(section))
+		for scanner.Scan() {
+			line := scanner.Text()
+			key, value, found := strings.Cut(line, ":")
+			if !found {
+				return nil, nil, xerrors.Errorf("Failed to parse APKINDEX line. err: unexpected APKINDEX format. expected: %q, actual: %q", "<Section>:<Content>", line)
+			}
+			switch key {
+			case "P":
+				name = value
+			case "V":
+				version = value
+			case "A":
+				arch = value
+			case "o":
+				srcName = value
+			}
+		}
+		if err := scanner.Err(); err != nil {
+			return nil, nil, xerrors.Errorf("Failed to scan by the scanner. err: %w", err)
+		}
+		if name == "" || version == "" {
+			return nil, nil, xerrors.Errorf("Failed to parse APKINDEX record. err: package name(P:) and package version(V:) are required fields in APKINDEX Record: %q", section)
+		}
+		if srcName == "" {
+			srcName = name
+		}
+
+		binaries[name] = models.Package{
+			Name:    name,
+			Version: version,
+			Arch:    arch,
+		}
+
+		src, ok := sources[srcName]
+		if !ok {
+			src = models.SrcPackage{
+				Name:    srcName,
+				Version: version,
+			}
+		}
+		src.AddBinaryName(name)
+		sources[srcName] = src
+	}
+
+	return binaries, sources, nil
+}
