index 00000000..c5c7386b
--- /dev/null
+++ b/model/album_artist.go
@@ -0,0 +1,101 @@
+package model
+
+import (
+	"crypto/md5"
+	"fmt"
+	"sort"
+	"strings"
+
+	"github.com/navidrome/navidrome/consts"
+)
+
+type AlbumArtistRef struct {
+	Name string
+	ID   string
+}
+
+func ArtistNameID(name string) string {
+	trimmed := strings.TrimSpace(name)
+	if strings.EqualFold(trimmed, consts.VariousArtists) {
+		return consts.VariousArtistsID
+	}
+	return fmt.Sprintf("%x", md5.Sum([]byte(strings.ToLower(trimmed))))
+}
+
+func ResolveTrackAlbumArtist(albumArtist, artist string) AlbumArtistRef {
+	name := strings.TrimSpace(albumArtist)
+	if name == "" {
+		name = strings.TrimSpace(artist)
+	}
+	if name == "" {
+		name = consts.UnknownArtist
+	}
+	return AlbumArtistRef{Name: name, ID: ArtistNameID(name)}
+}
+
+func ResolveAlbumArtist(compilation bool, artists ...AlbumArtistRef) AlbumArtistRef {
+	if len(artists) == 0 {
+		return ResolveTrackAlbumArtist("", "")
+	}
+
+	type countedArtist struct {
+		ref   AlbumArtistRef
+		count int
+	}
+
+	counts := map[string]*countedArtist{}
+	for _, artist := range artists {
+		ref := normalizeAlbumArtistRef(artist)
+		if current, ok := counts[ref.ID]; ok {
+			current.count++
+			if current.ref.Name == consts.UnknownArtist && ref.Name != consts.UnknownArtist {
+				current.ref.Name = ref.Name
+			}
+			continue
+		}
+		counts[ref.ID] = &countedArtist{ref: ref, count: 1}
+	}
+
+	if len(counts) == 1 {
+		for _, artist := range counts {
+			return artist.ref
+		}
+	}
+
+	if compilation {
+		return AlbumArtistRef{Name: consts.VariousArtists, ID: consts.VariousArtistsID}
+	}
+
+	resolved := make([]countedArtist, 0, len(counts))
+	for _, artist := range counts {
+		resolved = append(resolved, *artist)
+	}
+	sort.Slice(resolved, func(i, j int) bool {
+		if resolved[i].count != resolved[j].count {
+			return resolved[i].count > resolved[j].count
+		}
+		if resolved[i].ref.Name != resolved[j].ref.Name {
+			return resolved[i].ref.Name < resolved[j].ref.Name
+		}
+		return resolved[i].ref.ID < resolved[j].ref.ID
+	})
+	return resolved[0].ref
+}
+
+func normalizeAlbumArtistRef(artist AlbumArtistRef) AlbumArtistRef {
+	id := strings.TrimSpace(artist.ID)
+	name := strings.TrimSpace(artist.Name)
+
+	switch {
+	case name == "" && id == consts.VariousArtistsID:
+		name = consts.VariousArtists
+	case name == "":
+		name = consts.UnknownArtist
+	}
+
+	if id == "" {
+		id = ArtistNameID(name)
+	}
+
+	return AlbumArtistRef{Name: name, ID: id}
+}
