+func (c DatabaseConfig) hasConnectionFields() bool {
+	return c.Protocol != "" || c.Host != "" || c.Port != 0 || c.User != "" || c.Password != "" || c.Name != ""
+}
+
+func (c DatabaseConfig) ConnectionURL() (string, error) {
+	if c.URL != "" {
+		return c.URL, nil
+	}
+
+	if !c.hasConnectionFields() {
+		return "", nil
+	}
+
+	if c.Port < 0 {
