+		}
+		if c.User == "" {
+			return "", fliptErrors.EmptyFieldError(dbUser)
+		}
+		if c.Name == "" {
+			return "", fliptErrors.EmptyFieldError(dbName)
+		}
+
+		port := c.Port
+		if port == 0 {
+			port = 5432
+		}
+
+		return buildDatabaseURL("postgres", c.User, c.Password, c.Host, port, c.Name, map[string]string{
+			"sslmode": "disable",
+		}), nil
+	case "mysql":
+		if c.Host == "" {
+			return "", fliptErrors.EmptyFieldError(dbHost)
+		}
+		if c.User == "" {
+			return "", fliptErrors.EmptyFieldError(dbUser)
+		}
+		if c.Name == "" {
+			return "", fliptErrors.EmptyFieldError(dbName)
+		}
+
+		port := c.Port
+		if port == 0 {
+			port = 3306
+		}
+
+		return buildDatabaseURL("mysql", c.User, c.Password, c.Host, port, c.Name, nil), nil
+	default:
+		return "", fliptErrors.InvalidFieldError(dbProtocol, "must be one of 'file', 'postgres', or 'mysql'")
+	}
+}
+
+func normalizeDatabaseProtocol(protocol string) string {
+	switch strings.ToLower(strings.TrimSpace(protocol)) {
+	case "file", "sqlite", "sqlite3":
+		return "file"
+	case "postgres", "postgresql":
+		return "postgres"
+	case "mysql":
+		return "mysql"
+	default:
+		return strings.ToLower(strings.TrimSpace(protocol))
+	}
+}
+
+func buildDatabaseURL(scheme, user, password, host string, port int, name string, params map[string]string) string {
+	url := &neturl.URL{
+		Scheme: scheme,
+		User:   neturl.UserPassword(user, password),
+		Host:   net.JoinHostPort(host, strconv.Itoa(port)),
+		Path:   "/" + strings.TrimPrefix(name, "/"),
+	}
+
+	if password == "" {
+		url.User = neturl.User(user)
+	}
+
+	if len(params) > 0 {
+		values := neturl.Values{}
+		for key, value := range params {
+			values.Set(key, value)
+		}
+		url.RawQuery = values.Encode()
+	}
+
+	return url.String()
+}
